import { useState, useEffect, useCallback } from "react";
import { CandidateListRow } from "../services/IScorecardService";
import { ListNames } from "../../../../utilities/Config";
import {
  RecuritmentHRMsg,
  RoleName,
  WorkflowAction,
  workflowStatusApi,
} from "../config/ScorecardConfig";

import * as ScorecardApiService from "../services/ScorecardApiService";

interface UseCandidateListDataOptions {
  recruitmentID: number;
  jobCodeID: number;
  jobCode: string;
  employeeList: any[];
}

export function useCandidateListData({
  recruitmentID,
  jobCodeID,
  jobCode,
  employeeList,
}: UseCandidateListDataOptions) {
  const [candidateData, setCandidateData] = useState<CandidateListRow[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const load = useCallback(async () => {
    if (!jobCode || !recruitmentID) return;

    setIsLoading(true);

    try {
      const rows = await ScorecardApiService.fetchCandidateList(
        recruitmentID,
        jobCodeID,
        employeeList
      );

      setCandidateData(rows);
    } catch (err) {
      console.error("useCandidateListData – load error:", err);
      setCandidateData([]);
    } finally {
      setIsLoading(false);
    }
  }, [recruitmentID, jobCodeID, jobCode, employeeList]);

  useEffect(() => {
    void load();
  }, [load]);

  const handleBulkReject = useCallback(
    async (selectedCandidates: CandidateListRow[]) => {
      setIsLoading(true);

      let updateSuccess = false;

      try {
        const interviewedCount =
          await ScorecardApiService.getCandidateInterviewedCount(jobCodeID);

        for (const candidate of selectedCandidates) {
          try {
            const rejectionPayload = {
              workflowStatus: workflowStatusApi.CandidateRejectedIPanel,
              jobRequestId: Number(candidate.JobRequestID),
              comments: String(candidate.Comments ?? ""),
              actionBy: RoleName.HOD,
            };

            const actionPayload = {
              ActionId: WorkflowAction.Reject,
              Id: candidate.ID,
              ItemCreated: "Yes",
              Comments: String(candidate.Comments ?? ""),
              GPA: String(candidate.GPA ?? ""),
              OthersInterviewed:
                interviewedCount > 1 ? "Yes" : "No",
            };

            await ScorecardApiService.updateCandidateWorkflowStatus(
              rejectionPayload
            );

            const response =
              await ScorecardApiService.candidateSelectionApi(
                actionPayload,
                ListNames.HRMSRecruitmentCandidatePersonalDetails
              );

            if (response.status === 200) {
              updateSuccess = true;
            }
          } catch (err) {
            console.error(
              `Error rejecting candidate ID: ${candidate.ID}`,
              err
            );
          }
        }

        await load();

        return {
          success: updateSuccess,
          message: RecuritmentHRMsg.PositionIDassigned,
        };
      } finally {
        setIsLoading(false);
      }
    },
    [jobCodeID, load]
  );

  return {
    candidateData,
    isLoading,
    reload: load,
    handleBulkReject,
  };
}